const upsertCartItem = `-- name: UpsertCartItem :one
INSERT INTO cart_items (cart_id, product_unit_id, product_id, supplier_id, qty)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (cart_id, product_unit_id) DO UPDATE
SET qty = LEAST(99, cart_items.qty + EXCLUDED.qty)
RETURNING id, cart_id, product_unit_id, product_id, supplier_id, qty, created_at, updated_at
`

type UpsertCartItemParams struct {
	CartID        uuid.UUID
	ProductUnitID uuid.UUID
	ProductID     uuid.UUID
	SupplierID    uuid.UUID
	Qty           int32
}

// Adding the same pack again bumps quantity rather than creating a duplicate
// line, which is what a customer means by pressing Add twice.
func (q *Queries) UpsertCartItem(ctx context.Context, arg UpsertCartItemParams) (CartItem, error) {
	row := q.db.QueryRow(ctx, upsertCartItem,
		arg.CartID,
		arg.ProductUnitID,
		arg.ProductID,
		arg.SupplierID,
		arg.Qty,
	)
	var i CartItem
	err := row.Scan(
		&i.ID,
		&i.CartID,
		&i.ProductUnitID,
		&i.ProductID,
		&i.SupplierID,
		&i.Qty,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
